2: //! GET /api/plugins             — every plugin in the catalog
3: //! GET /api/plugin-schema/:id   — one plugin's schema
4: //!
5: //! The sealed catalog under `/dev/shm/opdbus/` is the single source of truth: a
6: //! plugin exists iff its blob is sealed there. These routes are deliberately
7: //! model-agnostic — nothing here depends on which inference model is in use.
8: 
9: use axum::{Json, extract::Path};
10: use op_blob::catalog;
11: use serde_json::{Value, json};
12: 
13: /// Every plugin actually present in the sealed blob catalog.
14: ///
15: /// This is NOT the same list as "plugins with generated RPC methods" — state-only
16: /// plugins have zero methods but are very much present as real blobs.
17: pub async fn plugin_list_handler() -> Result<Json<Value>, String> {
18:     match catalog::read_manifest_plugin_ids_shm() {
19:         Some(ids) => Ok(Json(json!({ "plugins": ids }))),
20:         None => Err("blob catalog manifest unavailable".to_string()),
21:     }
22: }
23: 
24: pub async fn plugin_schema_handler(Path(plugin_id): Path<String>) -> Result<Json<Value>, String> {
25:     match catalog::read_plugin_schema_shm(&plugin_id) {
26:         Some(schema) => Ok(Json(
27:             serde_json::to_value(schema).map_err(|e| e.to_string())?,
28:         )),
29:         None => Err(format!("Plugin schema not found: {plugin_id}")),
30:     }
31: }

